from pathlib import Path

import numpy as np

from src.mythosmini.config import EOS_TOKEN_ID
from src.mythosmini.data.procedural import (
    BRACKET_PAIRS,
    build_procedural_cache,
    generate_dyck_sequence,
)


def is_balanced(sequence: list[int]) -> bool:
    closers = {opener: closer for opener, closer in BRACKET_PAIRS}
    stack: list[int] = []
    for token in sequence:
        if token in closers:
            stack.append(closers[token])
        elif stack and token == stack[-1]:
            stack.pop()
        else:
            return False
    return not stack


def test_generate_dyck_sequence_is_balanced() -> None:
    rng = np.random.default_rng(7)
    for _ in range(20):
        sequence = generate_dyck_sequence(rng, max_depth=8, target_length=64)
        assert sequence
        assert is_balanced(sequence)


def test_generate_dyck_sequence_uses_only_bracket_tokens() -> None:
    rng = np.random.default_rng(3)
    allowed = {token for pair in BRACKET_PAIRS for token in pair}
    sequence = generate_dyck_sequence(rng, max_depth=8, target_length=128)
    assert set(sequence) <= allowed


def test_build_procedural_cache_exact_size_and_separators(tmp_path: Path) -> None:
    destination = tmp_path / "proc.u16"
    path = build_procedural_cache(10_000, destination, seed=11)
    tokens = np.fromfile(path, dtype=np.uint16)
    assert tokens.shape[0] == 10_000
    assert (tokens <= EOS_TOKEN_ID).all()
    assert (tokens == EOS_TOKEN_ID).sum() > 0


def test_build_procedural_cache_deterministic(tmp_path: Path) -> None:
    first = np.fromfile(build_procedural_cache(5_000, tmp_path / "a.u16", seed=5), dtype=np.uint16)
    second = np.fromfile(build_procedural_cache(5_000, tmp_path / "b.u16", seed=5), dtype=np.uint16)
    assert np.array_equal(first, second)


def test_build_procedural_cache_rejects_bad_size(tmp_path: Path) -> None:
    try:
        build_procedural_cache(0, tmp_path / "c.u16", seed=1)
        raise AssertionError("expected ValueError")
    except ValueError:
        pass

